import{_ as e,o as a,c as d,a2 as n}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"HTML5 专题","description":"","frontmatter":{},"headers":[],"relativePath":"前端/html5/index.md","filePath":"前端/html5/index.md","lastUpdated":1792894072000}'),o={name:"前端/html5/index.md"};function r(s,t,l,i,c,p){return a(),d("div",null,[...t[0]||(t[0]=[n(`<h1 id="html5-专题" tabindex="-1">HTML5 专题 <a class="header-anchor" href="#html5-专题" aria-label="Permalink to &quot;HTML5 专题&quot;">​</a></h1><blockquote><p>JD 第一行就写 HTML5。这个专题把&quot;浏览器新能力&quot;这块补齐：<strong>语义化结构、文件与二进制、Canvas 图形、离线与实时通信</strong>。</p></blockquote><hr><h2 id="📚-章节列表" tabindex="-1">📚 章节列表 <a class="header-anchor" href="#📚-章节列表" aria-label="Permalink to &quot;📚 章节列表&quot;">​</a></h2><ol><li><a href="./1-语义化与文档结构">语义化与文档结构</a> — 语义标签、SEO 可访问性、表单增强、DOM 解析</li><li><a href="./2-文件与二进制">文件与二进制</a> — File / Blob / FileReader / 拖拽 / 下载 / 图片处理</li><li><a href="./3-canvas与图形">Canvas 与图形</a> — 2D 绘制、离屏、性能、WebGL / SVG 对比</li><li><a href="./4-离线与实时通信">离线与实时通信</a> — IndexedDB / Service Worker / WebSocket / SSE / Web Worker</li></ol><hr><h2 id="速查表-html5-到底带来什么" tabindex="-1">速查表：HTML5 到底带来什么 <a class="header-anchor" href="#速查表-html5-到底带来什么" aria-label="Permalink to &quot;速查表：HTML5 到底带来什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>关键 API</th><th>典型场景</th></tr></thead><tbody><tr><td>语义结构</td><td><code>&lt;header&gt; &lt;nav&gt; &lt;main&gt; &lt;article&gt; &lt;aside&gt; &lt;footer&gt;</code></td><td>SEO、无障碍、SEO 爬虫理解页面</td></tr><tr><td>表单增强</td><td><code>type=email/datetime/color/range</code>、<code>datalist</code>、<code>FormData</code></td><td>移动端原生键盘、免 JS 校验</td></tr><tr><td>多媒体</td><td><code>&lt;video&gt; &lt;audio&gt;</code> + Media Source Extensions</td><td>音视频播放</td></tr><tr><td>图形</td><td><code>&lt;canvas&gt;</code>、<code>&lt;svg&gt;</code>、WebGL</td><td>图表、大屏、游戏、图像处理</td></tr><tr><td>本地存储</td><td>localStorage / sessionStorage / IndexedDB</td><td>登录态、离线草稿、大数据缓存</td></tr><tr><td>离线</td><td>Service Worker + Cache API + Manifest</td><td>PWA、弱网可用</td></tr><tr><td>通信</td><td>WebSocket / SSE / fetch / Beacon</td><td>实时推送、埋点上报</td></tr><tr><td>设备能力</td><td>Geolocation、Notification、Clipboard、File API</td><td>定位、推送、剪贴板、附件</td></tr><tr><td>多线程</td><td>Web Worker</td><td>大文件解析、加密、图片处理</td></tr><tr><td>媒体采集</td><td>MediaRecorder、getUserMedia</td><td>录音、摄像头</td></tr><tr><td>渲染调度</td><td><code>requestAnimationFrame</code>、IntersectionObserver</td><td>动画、懒加载</td></tr></tbody></table><hr><h2 id="面试提醒" tabindex="-1">面试提醒 <a class="header-anchor" href="#面试提醒" aria-label="Permalink to &quot;面试提醒&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问 &quot;HTML5 有什么新特性&quot; 时，不要只答&quot;新增了语义化标签和 Canvas&quot;。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>高分答法（分三层）:</span></span>
<span class="line"><span>1. 语义与可访问性:标签不是换皮,它决定了 AT(读屏软件)怎么朗读、SEO 怎么理解页面结构</span></span>
<span class="line"><span>2. 能力开放:Canvas/WebGL(图形)、File API(本地文件)、Geolocation/Notification(设备能力)、</span></span>
<span class="line"><span>             IndexedDB(结构化本地存储)、MediaRecorder(音视频采集)</span></span>
<span class="line"><span>3. 工程影响:Service Worker 改变了缓存模型、Worker 改变了线程模型、fetch/CORS 改变了请求模型,</span></span>
<span class="line"><span>             这些才是真正影响前端架构的部分</span></span></code></pre></div>`,11)])])}const u=e(o,[["render",r]]);export{b as __pageData,u as default};
